#!/bin/bash
# 前への跳躍の角運動量の出どころ（2026-11-02、DIAG_H=1）。TV3R の設定＋JUMP_VX＋足を止まり点へ（c）、m00 の状況。j25。
cd /home/takara/work/dp/articara
source ./setup-mujoco.sh >/dev/null
D=log/claude_g1jump_20261021; B=$D/g1_flight_probe_j25; O=$D/diagh
common="ROBOT=g1 WBC_STRATEGY=weighted T=7 FLIGHT_FEET=1 LAND_ABSORB=1 LAND_T=0.20 JUMP_RELEASE=1 MOM_TASK=1 WBCW_CONTACT=1 WBCW_MOMENTUM=1 CROUCH=0.18 JUMP_Z_TO=0.0 INIT_SEED=1 INIT_JITTER=0.01 MU_GROUND=0.7 T_LAUNCH=1.2 PLANT_MASS_SCALE=1.0 JUMP_ABORT=1 JUMP_PUSH_R=0.3 QD_CLAMP=40 DIAG_TD=1 FLIGHT_FEET_FLAT=1 DIAG_HX=1 RELEASE_FIRST_OFF=1 WBCW_CONTACT_REST=0.1 WBCW_TRUNK_LAND_VZ=0.7 WBCW_TRUNK_LAND=0.03 FALL_TILT=1.5 LAND_REF_FOLLOW=2 AIR_ABORT_T=0.08 DIAG_H=1 FLIGHT_FEET_CAPTURE=1 FLIGHT_FEET_CAPTURE_T=0.06 KP_FLIGHT_FEET=1000 KD_FLIGHT_FEET=63"
for v in 1.5 2.0; do for vx in 0 0.2 0.4; do
  env $common JUMP_V=$v JUMP_VX=$vx TRAJ_CSV=$O/V${v}_vx${vx}.csv $B > $O/V${v}_vx${vx}.log 2>&1 &
done; done
wait
echo "#### DIAGH_DONE"
env ROBOT=g1 WBC_STRATEGY=weighted T=7 FLIGHT_FEET=1 LAND_ABSORB=1 LAND_T=0.20 JUMP_RELEASE=1 MOM_TASK=1 WBCW_CONTACT=1 WBCW_MOMENTUM=1 CROUCH=0.18 JUMP_Z_TO=0.0 INIT_SEED=1 INIT_JITTER=0.01 MU_GROUND=0.7 T_LAUNCH=1.2 PLANT_MASS_SCALE=1.0 JUMP_ABORT=1 JUMP_PUSH_R=0.3 QD_CLAMP=40 DIAG_TD=1 FLIGHT_FEET_FLAT=1 DIAG_HX=1 RELEASE_FIRST_OFF=1 WBCW_CONTACT_REST=0.1 WBCW_TRUNK_LAND_VZ=0.7 WBCW_TRUNK_LAND=0.03 FALL_TILT=1.5 LAND_REF_FOLLOW=2 AIR_ABORT_T=0.08 DIAG_H=1 JUMP_V=2.0 TRAJ_CSV=log/claude_g1jump_20261021/diagh/V2.0_tv3r.csv log/claude_g1jump_20261021/g1_flight_probe_base_tv3r
